 "verbo-11": {"promptNative":"J’espère qu’ils ___ (estar = être) bien.","explain":"La forme ils/elles de « estar » (subjonctif présent) est « estejam ».","wrongNote":"La forme dont cette phrase a besoin est « estejam » (estar). La forme ils/elles de « estar » (subjonctif présent) est « estejam ».","distractorNotes":{"esteja":"« esteja » est une autre forme de estar, mais pas le temps/mode qu’exige cette phrase — ici, c’est « estejam » qui convient.","estejas":"« estejas » est une autre forme de estar, mais pas le temps/mode qu’exige cette phrase — ici, c’est « estejam » qui convient.","estejamos":"« estejamos » est une autre forme de estar, mais pas le temps/mode qu’exige cette phrase — ici, c’est « estejam » qui convient."}},
 "verbo-12": {"promptNative":"Tu ___ (ser = être) portugais.","explain":"La forme tu de « ser » (présent) est « és ».","wrongNote":"La forme qu’exige cette phrase est « és » (ser). La forme tu de « ser » (présent) est « és ».","distractorNotes":{"é":"« é » est une autre forme de ser, mais pas le temps/mode qu’exige cette phrase — ici, c’est « és » qui convient.","somos":"« somos » est une forme de première personne du pluriel (nós / nous), mais le sujet de cette phrase demande « és ».","sou":"« sou » est une autre forme de ser, mais pas le temps/mode qu’exige cette phrase — ici, c’est « és » qui convient."}},
 "verbo-13": {"promptNative":"Il ___ (ser = être) portugais.","explain":"La forme il/elle de « ser » (présent) est « é ».","wrongNote":"La forme qu’exige cette phrase est « é » (ser). La forme il/elle de « ser » (présent) est « é ».","distractorNotes":{"és":"« és » est une autre forme de ser, mais pas le temps/mode qu’exige cette phrase — ici, c’est « é » qui convient.","sou":"« sou » est une autre forme de ser, mais pas le temps/mode qu’exige cette phrase — ici, c’est « é » qui convient.","são":"« são » est une forme de première personne (eu / je), mais le sujet de cette phrase demande « é »."}},
